"""
Majorana charged-current gauge sector

Evaluate G^W of the scientific input below, the charged-current portion of source Eq. (2.22).

Scientific input for this coding step:

Let m[i] denote the neutrino Takagi masses and l[a] the charged-lepton masses.
All displayed sums run over the complete flavor or neutrino range subject to the stated exclusion. A star is complex conjugation; C = B dagger B.
kappa = alpha / (32*pi*sw2*mW**2), qW = xiW*mW**2, qZ = xiZ*mZ**2.
L[a,k] = B0(l[a]**2; m[k], sqrt(qW)),
W[i,r] = B0(m[i]**2; l[r], sqrt(qW)),
Z[i,k] = B0(m[i]**2; m[k], sqrt(qZ)).
The gauge sector is G = Gell + GW + GZ + Gd, with components

Gell[a,i] = kappa * sum_{b != a,k} B[a,k]*conj(B[b,k])*B[b,i]
    * ((m[k]**2-l[a]**2+qW)*L[a,k] - (m[k]**2-l[b]**2+qW)*L[b,k]).

GW[a,i] = kappa * sum_{j != i,r} B[a,j]*conj(B[r,j])*B[r,i]
    * ((m[j]**2-l[r]**2-qW)*W[j,r] - (m[i]**2-l[r]**2-qW)*W[i,r]).

GZ[a,i] = (kappa/2) * sum_{j != i,k} B[a,j] * (
    (C[j,k]*C[k,i]*(m[j]**2-m[k]**2-qZ)
     - conj(C[j,k])*C[k,i]*(m[k]/m[j])*(m[j]**2-m[k]**2+qZ))*Z[j,k]
    - (C[j,k]*C[k,i]*(m[i]**2-m[k]**2-qZ)
       - C[j,k]*conj(C[k,i])*(m[k]/m[i])*(m[i]**2-m[k]**2+qZ))*Z[i,k]).

Gd[a,i] = -(kappa*B[a,i]/2) * sum_k (m[k]/m[i])
    * (m[i]**2-m[k]**2+qZ) * (C[k,i]**2-C[i,k]**2) * Z[i,k].

GZ is the off-diagonal external-neutrino contribution; Gd is its Majorana diagonal counterpart. These are the source's Eq. (2.19) and the gauge sector of Eq. (2.22).
Each loop or correction has final axis [coefficient of Delta, finite part].
The public APIs specify positive-mass spectra, array orders and comparison conventions.

Returns
-------
return result
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def neutrino_w_gauge(b: 'np.ndarray', m: 'np.ndarray', ml: 'np.ndarray', mw: float, alpha: float, sw2: float, xi_w: float, loops: 'np.ndarray') -> 'np.ndarray':
    """Majorana charged-current gauge sector.

    Parameters
    ----------
    b : complex ndarray, shape (n,N), N=2*n, 1 <= n <= 3
        Charged-current mixing, b b.H=I and b diag(m) b.T=0.
    m : float ndarray, shape (N,)
        Positive Majorana masses in GeV, ordered like b columns.
    ml : float ndarray, shape (n,)
        Nonnegative charged-lepton masses in GeV, in b row order.
    mw : float
        Positive W mass in GeV.
    alpha, sw2 : float
        Positive alpha and 0 < sin(theta_W)^2 < 1.
    xi_w : float
        Nonnegative W gauge parameter.
    loops : float ndarray, shape (N,n,2)
        Indices: external neutrino, internal charged lepton, Laurent column.
        Final-axis order [Delta coefficient, finite part], as defined for
        W in the common background; entries are dimensionless.

    Returns
    -------
    result : complex ndarray, shape (n,N,2)
        Dimensionless G^W, active row then mass column then Laurent
        axis [Delta coefficient, finite part].
    """
    return result

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np
from scipy.linalg import eigh

def _oracle_neutrino_w_gauge(b: 'np.ndarray', m: 'np.ndarray', ml: 'np.ndarray', mw: float, alpha: float, sw2: float, xi_w: float, loops: 'np.ndarray') -> 'np.ndarray':
    b,m,ml,loops=np.asarray(b),np.asarray(m),np.asarray(ml),np.asarray(loops)
    out=np.zeros(b.shape+(2,),complex)
    for i,x in enumerate(m):
        for j,y in enumerate(m):
            if i==j:continue
            for r,l in enumerate(ml):
                val=(y*y-xi_w*mw**2-l*l)*loops[j,r]-(x*x-xi_w*mw**2-l*l)*loops[i,r]
                out[:,i]+=b[:,j,None]*b[r,j].conjugate()*b[r,i]*val
    return alpha/(32*np.pi*sw2*mw**2)*out

